                    for xa in ra:
                        for xb in rb:
                            gap=abs(xa-xb)-1
                            if gap>0:
                                lo,hi=min(xa,xb),max(xa,xb)
                                cand.append((gap,[ (i,x) for x in range(lo+1,hi)]))
